script:
(function () {
  'use strict';
  // Educational risk-tolerance questionnaire with three asset classes: cash, fixed income and
  // equities. Not investment advice.
  //   Seven questions, each answer worth 1 to 4 points; score = sum, 7 to 28.
  //   Score bands 7-10, 11-14, 15-19, 20-24, 25-28 map to five illustrative profiles, each a fixed
  //   hypothetical cash / fixed income / equity split (every split totals 100%).
  //   Dollar split = amount x each percentage (rounded to whole dollars for display only).
  // Checked in Node (aq5/tests/q.test.js): every split totals 100%; band edges 7, 10, 11, 14, 15, 19,
  // 20, 24, 25, 28 land in the right profile; $50,000 in the balanced split = $5,000 / $22,500 /
  // $22,500; fewer than seven answers shows no profile.
  var QUESTIONS = 7;
  var PROFILES = [
    { min: 7, max: 10, name: 'Capital preservation', mix: [40, 50, 10],
      text: 'Answers in this range put stability and quick access first. The illustrative split keeps most of the money in cash and fixed income.' },
    { min: 11, max: 14, name: 'Income', mix: [20, 60, 20],
      text: 'Answers in this range favor steady income and limited swings. The illustrative split centers on fixed income with a smaller equity share.' },
    { min: 15, max: 19, name: 'Balanced', mix: [10, 45, 45],
      text: 'Answers in this range weigh growth and stability about equally. The illustrative split divides most of the money between fixed income and equities.' },
    { min: 20, max: 24, name: 'Growth', mix: [5, 30, 65],
      text: 'Answers in this range accept larger swings for more growth over time. The illustrative split is mostly equities.' },
    { min: 25, max: 28, name: 'Aggressive growth', mix: [0, 15, 85],
      text: 'Answers in this range point to a long time frame and comfort with deep temporary losses. The illustrative split is nearly all equities.' }
  ];
  var CLASSES = ['Cash', 'Fixed income', 'Equities'];

  // --- calc start
  function profileFor(score) {
    for (var i = 0; i < PROFILES.length; i++) {
      if (score >= PROFILES[i].min && score <= PROFILES[i].max) return i;
    }
    return -1;
  }
  function split(amount, mix) { return mix.map(function (p) { return amount * p / 100; }); }
  // --- calc end

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function set(id, text) { document.getElementById(id).textContent = text; }

  function answers() {
    var vals = [];
    for (var q = 1; q <= QUESTIONS; q++) {
      var r = document.querySelector('input[name="qcQ' + q + '"]:checked');
      vals.push(r ? parseInt(r.value, 10) : null);
    }
    return vals;
  }

  function cell(text, header) {
    var td = document.createElement(header ? 'th' : 'td');
    if (header) td.setAttribute('scope', 'row');
    td.textContent = text;
    return td;
  }

  function update() {
    var vals = answers(), done = vals.filter(function (v) { return v !== null; }).length;
    var score = vals.reduce(function (a, v) { return a + (v || 0); }, 0);
    var amount = parseFloat(document.getElementById('qcAmount').value);
    var error = document.getElementById('qcError');
    var badAmount = isNaN(amount) || amount < 0;
    error.hidden = !badAmount;
    if (badAmount) error.textContent = 'Enter an amount of $0 or more to see the dollar split.';
    set('qcProgress', done + ' of ' + QUESTIONS + ' questions answered');
    var k = done === QUESTIONS ? profileFor(score) : -1;

    var body = document.getElementById('qcProfiles');
    body.textContent = '';
    PROFILES.forEach(function (p, i) {
      var tr = document.createElement('tr');
      tr.appendChild(cell(p.name + (i === k ? ' (your score)' : ''), true));
      tr.appendChild(cell(p.min + '–' + p.max));
      p.mix.forEach(function (x) { tr.appendChild(cell(x + '%')); });
      if (i === k) tr.className = 'font-semibold';
      body.appendChild(tr);
    });

    var ids = ['qcCash', 'qcFixed', 'qcEquity'];
    var dollars = document.getElementById('qcDollars');
    dollars.textContent = '';
    if (k < 0) {
      set('qcScore', done ? score + ' so far' : '–');
      set('qcProfile', 'Answer every question');
      set('qcProfileText', 'The score and the matching illustrative split appear once all ' + QUESTIONS + ' questions are answered.');
      ids.forEach(function (id) { set(id, '–'); });
      return;
    }
    var p = PROFILES[k];
    set('qcScore', score + ' of 28');
    set('qcProfile', p.name);
    set('qcProfileText', p.text);
    ids.forEach(function (id, i) { set(id, p.mix[i] + '%'); });
    if (!badAmount) {
      var parts = split(amount, p.mix);
      CLASSES.forEach(function (name, i) {
        var tr = document.createElement('tr');
        tr.appendChild(cell(name, true));
        tr.appendChild(cell(p.mix[i] + '%'));
        tr.appendChild(cell(money.format(parts[i])));
        dollars.appendChild(tr);
      });
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('qcForm');
    form.addEventListener('change', update);
    form.addEventListener('input', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    form.addEventListener('reset', function () { setTimeout(update, 0); });
    update();
  });
})();
